CREATE OR REPLACE MODEL `ent-kixavvik-dev.disruptions.exp_togvarsel_lr_am10_f15cat_A` OPTIONS(model_type='LOGISTIC_REG', l2_reg=0.5, max_iterations=50, data_split_method='NO_SPLIT', input_label_cols=['label']) AS
SELECT f.et_t5_0630, f.et_cx_0630, f.et_cxj_0630, f.et_md_0630, f.prev_eve_t5, f.prev_eve_cancel, f.prev_pm_t5, f.sx_inn_0630, f.sx_infra_0630, f.sx_amj_0630, f.sx_amj_inn_0630, f.sx_mt_0630, f.sx_big_0630, f.sx_n_0630, CAST(f.dow AS STRING) dow_s, f.low_season, g.cat_drift_ruteendring_0630, g.cat_drift_kapasitet_0630, g.cat_materiell_teknisk_0630, g.cat_infrastruktur_signal_0630, g.cat_infrastruktur_spor_0630, g.cat_infrastruktur_strom_0630, g.cat_infrastruktur_sporveksel_0630, g.cat_drift_personale_0630, g.cat_ytre_tredjepart_0630, g.cat_drift_planlagt_0630, g.cat_infrastruktur_stasjon_0630, g.cat_vaer_0630, g.cat_other_0630, g.catj_infra_am_0630, g.catj_mat_am_0630, g.catj_drift_am_0630, f.am_t10 >= 0.10 AS label FROM `ent-kixavvik-dev.disruptions.togvarsel_features` f JOIN `ent-kixavvik-dev.disruptions.exp_togvarsel_features2` g USING (d) WHERE f.weekday AND NOT f.holiday AND f.am_n > 300 AND f.pm_n > 300 AND f.d < '2026-04-01';
CREATE OR REPLACE TABLE `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_lr_am10_f15cat_A` AS
